scripts.host.probe:
{
  "schema": 1,
  "timeout_ms": 360000,
  "step_timeout_ms": 60000,
  "label_dump": {
    "every_ms": 5000
  },
  "steps": [
    {
      "op": "wait",
      "editing": true
    },
    {
      "op": "assert_relay"
    },
    {
      "op": "editor_pick",
      "input_player": 0
    },
    {
      "op": "editor_move",
      "input_player": 0,
      "x_fraction": 0.48
    },
    {
      "op": "wait",
      "renders": 5,
      "elapsed_ms": 1000
    },
    {
      "op": "menu",
      "command": "video_mark valid-preview-host"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200,
      "scope": "menu"
    },
    {
      "op": "screenshot_pair",
      "name": "valid-preview-host",
      "scope": "menu"
    },
    {
      "op": "assert_editor",
      "input_player": 0,
      "equals": {
        "screen_text": "Valid spot - click to INSTALL your brain"
      }
    },
    {
      "op": "assert_net_ui_clear",
      "player": 0
    },
    {
      "op": "assert_control",
      "control": "LabelNetMatchStatus",
      "text_contains": "0 of 2",
      "fits": true,
      "inside": "BoxNetMatchStatus"
    },
    {
      "op": "game_mouse",
      "button": "left",
      "down": true
    },
    {
      "op": "wait",
      "renders": 3,
      "sim_advanced": 2
    },
    {
      "op": "game_mouse",
      "button": "left",
      "down": false
    },
    {
      "op": "wait",
      "renders": 3
    },
    {
      "op": "wait",
      "setup_ready": 1
    },
    {
      "op": "menu",
      "command": "video_mark placed-host"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200,
      "scope": "menu"
    },
    {
      "op": "screenshot_pair",
      "name": "placed-host",
      "scope": "menu"
    },
    {
      "op": "assert_editor",
      "input_player": 0,
      "equals": {
        "ready": true,
        "submitted": true,
        "screen_text": "READY to start - wait for others to finish..."
      }
    },
    {
      "op": "assert_net_ui_clear",
      "player": 0
    },
    {
      "op": "assert_control",
      "control": "LabelNetMatchStatus",
      "text_contains": "1 of 2",
      "fits": true,
      "inside": "BoxNetMatchStatus"
    },
    {
      "op": "key_down",
      "key": "Return"
    },
    {
      "op": "wait",
      "renders": 3,
      "sim_advanced": 2
    },
    {
      "op": "key_up",
      "key": "Return"
    },
    {
      "op": "wait",
      "renders": 3
    },
    {
      "op": "wait",
      "editing": false,
      "paused": false
    },
    {
      "op": "assert",
      "equals": {
        "setup_ready": 2,
        "setup_humans": 2,
        "local_actor_alive": true
      }
    },
    {
      "op": "assert_scene",
      "input_player": 0,
      "equals": {
        "alive": true,
        "brain_count": 2
      }
    },
    {
      "op": "menu",
      "command": "video_mark playing-host"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200,
      "scope": "menu"
    },
    {
      "op": "screenshot_pair",
      "name": "playing-host",
      "scope": "menu"
    },
    {
      "op": "game_mouse",
      "button": "right",
      "down": true
    },
    {
      "op": "wait",
      "renders": 3,
      "sim_advanced": 2
    },
    {
      "op": "wait_scene",
      "input_player": 0,
      "equals": {
        "pie_visible": true
      }
    },
    {
      "op": "pie_point",
      "input_player": 0,
      "command": 6
    },
    {
      "op": "wait_scene",
      "input_player": 0,
      "equals": {
        "pie_description": "Buy Menu - click to open"
      }
    },
    {
      "op": "menu",
      "command": "video_mark pie-buy-host"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200,
      "scope": "menu"
    },
    {
      "op": "screenshot_pair",
      "name": "pie-buy-host",
      "scope": "menu"
    },
    {
      "op": "assert_pie",
      "input_player": 0,
      "equals": {
        "visible": true,
        "description": "Buy Menu - click to open"
      }
    },
    {
      "op": "game_mouse",
      "button": "left",
      "down": true
    },
    {
      "op": "wait",
      "renders": 3,
      "sim_advanced": 2
    },
    {
      "op": "game_mouse",
      "button": "left",
      "down": false
    },
    {
      "op": "wait",
      "renders": 3
    },
    {
      "op": "game_mouse",
      "button": "right",
      "down": false
    },
    {
      "op": "wait",
      "renders": 5,
      "elapsed_ms": 1200
    },
    {
      "op": "menu",
      "command": "video_mark shop-host"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200,
      "scope": "menu"
    },
    {
      "op": "screenshot_pair",
      "name": "shop-host",
      "scope": "menu"
    },
    {
      "op": "assert_buy",
      "input_player": 0,
      "equals": {
        "visible": true,
        "enabled": true,
        "buy_allowed": true
      }
    },
    {
      "op": "menu",
      "command": "activate OrderClearButton",
      "scope": "buy",
      "input_player": 0
    },
    {
      "op": "menu",
      "command": "activate CraftTab",
      "scope": "buy",
      "input_player": 0
    },
    {
      "op": "shop_pick",
      "input_player": 0,
      "preset": "Base.rte/Rocket MK2"
    },
    {
      "op": "menu",
      "command": "activate BodiesTab",
      "scope": "buy",
      "input_player": 0
    },
    {
      "op": "shop_pick",
      "input_player": 0,
      "preset": "Coalition.rte/Soldier Light"
    },
    {
      "op": "menu",
      "command": "activate GunsTab",
      "scope": "buy",
      "input_player": 0
    },
    {
      "op": "shop_pick",
      "input_player": 0,
      "preset": "Coalition.rte/Assault Rifle"
    },
    {
      "op": "menu",
      "command": "video_mark order-host"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200,
      "scope": "menu"
    },
    {
      "op": "screenshot_pair",
      "name": "order-host",
      "scope": "menu"
    },
    {
      "op": "assert_buy",
      "input_player": 0,
      "equals": {
        "cart": [
          "Coalition.rte/Soldier Light",
          "Coalition.rte/Assault Rifle"
        ],
        "craft": "Base.rte/Rocket MK2",
        "passengers": 1
      },
      "remember": "order"
    },
    {
      "op": "assert_control",
      "scope": "buy",
      "input_player": 0,
      "control": "BuyButton",
      "equals": {
        "visible": true,
        "enabled": true
      },
      "fits": true,
      "inside": "BuyGUIBox"
    },
    {
      "op": "menu",
      "command": "activate BuyButton",
      "scope": "buy",
      "input_player": 0
    },
    {
      "op": "landing_zone_move",
      "input_player": 0,
      "within_ms": 15000
    },
    {
      "op": "menu",
      "command": "video_mark landing-zone-host"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200,
      "scope": "menu"
    },
    {
      "op": "screenshot_pair",
      "name": "landing-zone-host",
      "scope": "menu"
    },
    {
      "op": "assert_scene",
      "input_player": 0,
      "equals": {
        "landing_zone_selection": true,
        "screen_text": "Choose your landing zone... Hold UP or DOWN to place multiple orders"
      }
    },
    {
      "op": "game_mouse",
      "button": "left",
      "down": true
    },
    {
      "op": "wait",
      "renders": 3,
      "sim_advanced": 2
    },
    {
      "op": "game_mouse",
      "button": "left",
      "down": false
    },
    {
      "op": "wait",
      "renders": 3
    },
    {
      "op": "wait_scene",
      "input_player": 0,
      "funds_delta_from": "order"
    },
    {
      "op": "assert_scene",
      "input_player": 0,
      "funds_delta_from": "order"
    },
    {
      "op": "wait_scene",
      "input_player": 0,
      "delivered": "Coalition.rte/Soldier Light"
    },
    {
      "op": "menu",
      "command": "video_mark arrival-host"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200,
      "scope": "menu"
    },
    {
      "op": "screenshot_pair",
      "name": "arrival-host",
      "scope": "menu"
    },
    {
      "op": "assert_scene",
      "input_player": 0,
      "delivered": "Coalition.rte/Soldier Light",
      "equals": {
        "alive": true
      }
    },
    {
      "op": "actor_next_until",
      "input_player": 0,
      "preset": "Coalition.rte/Soldier Light"
    },
    {
      "op": "wait_scene",
      "input_player": 0,
      "equals": {
        "preset": "Coalition.rte/Soldier Light",
        "weapon": "Coalition.rte/Assault Rifle"
      }
    },
    {
      "op": "aim_brain",
      "input_player": 0,
      "target_player": 1
    },
    {
      "op": "game_mouse",
      "down": true
    },
    {
      "op": "wait",
      "elapsed_ms": 12000
    },
    {
      "op": "game_mouse",
      "down": false
    },
    {
      "op": "wait",
      "scope": "menu",
      "screen": "MultiplayerScreen",
      "control": "LabelMultiplayerStatus",
      "text_contains": "Waiting for Joiner to press Ready",
      "within_ms": 90000
    },
    {
      "op": "menu",
      "command": "video_mark brain-loss-host"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200,
      "scope": "menu"
    },
    {
      "op": "screenshot_pair",
      "name": "brain-loss-host",
      "scope": "menu"
    },
    {
      "op": "menu",
      "command": "assert_label LabelLastMatchSummary Brain"
    },
    {
      "op": "menu",
      "command": "assert_label LabelLastMatchSummary SkirmishDefense.lua:397"
    },
    {
      "op": "menu",
      "command": "assert_text_fits LabelLastMatchSummary"
    },
    {
      "op": "signal",
      "name": "done",
      "scope": "menu"
    },
    {
      "op": "finish"
    }
  ],
  "activate_phase": "Running",
  "sim_clock": "lockstep"
}

